		ctx.moveTo(0, radius*2 + neck_height);
		ctx.lineTo(width, radius*2 + neck_height);
		//left leg
		ctx.moveTo(width / 2, height - leg_height);
		ctx.lineTo(0, height);
		//right leg
		ctx.moveTo(width / 2, height - leg_height);
		ctx.lineTo(width, height);

		ctx.fill();
		ctx.stroke();
	}

}

